%2040.55%20L5%2038.26%20L6%2036.01%20L7%2033.82%20L8%2031.69%20L9%2029.64%20L10%2027.66%20L11%2025.78%20L12%2023.99%20L13%2022.30%20L14%2020.72%20L15%2019.26%20L16%2017.92%20L17%2016.70%20L18%2015.62%20L19%2014.67%20L20%2013.86%20L21%2013.19%20L22%2012.67%20L23%2012.30%20L24%2012.07%20L25%2012.00%20L26%2012.07%20L27%2012.30%20L28%2012.67%20L29%2013.19%20L30%2013.86%20L31%2014.67%20L32%2015.62%20L33%2016.70%20L34%2017.92%20L35%2019.26%20L36%2020.72%20L37%2022.30%20L38%2023.99%20L39%2025.78%20L40%2027.66%20L41%2029.64%20L42%2031.69%20L43%2033.82%20L44%2036.01%20L45%2038.26%20L46%2040.55%20L47%2042.88%20L48%2045.24%20L49%2047.61%20L50%2050.00%20L51%2052.39%20L52%2054.76%20L53%2057.12%20L54%2059.45%20L55%2061.74%20L56%2063.99%20L57%2066.18%20L58%2068.31%20L59%2070.36%20L60%2072.34%20L61%2074.22%20L62%2076.01%20L63%2077.70%20L64%2079.28%20L65%2080.74%20L66%2082.08%20L67%2083.30%20L68%2084.38%20L69%2085.33%20L70%2086.14%20L71%2086.81%20L72%2087.33%20L73%2087.70%20L74%2087.93%20L75%2088.00%20L76%2087.93%20L77%2087.70%20L78%2087.33%20L79%2086.81%20L80%2086.14%20L81%2085.33%20L82%2084.38%20L83%2083.30%20L84%2082.08%20L85%2080.74%20L86%2079.28%20L87%2077.70%20L88%2076.01%20L89%2074.22%20L90%2072.34%20L91%2070.36%20L92%2068.31%20L93%2066.18%20L94%2063.99%20L95%2061.74%20L96%2059.45%20L97%2057.12%20L98%2054.76%20L99%2052.39%20L100%2050.00%27%20fill%3D%27none%27%20stroke%3D%27black%27%20stroke-width%3D%273%27%20stroke-linejoin%3D%27round%27%20vector-effect%3D%27non-scaling-stroke%27/%3E%3C/svg%3E") 0 0 / 100% 100% no-repeat; }
.si .wave .mid { position: absolute; left: 0; right: 0; top: 50%; border-top: 1px dashed color-mix(in srgb, var(--muted) 45%, transparent); }
.si .wave .mid span { position: absolute; right: 0; bottom: 3px; font-size: 11px; color: var(--muted); }
.si .wave b { position: absolute; width: 18px; height: 18px; margin: -9px 0 0 -9px; border-radius: 50%; background: var(--accent);
  box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 22%, transparent); }
.si .wave-l { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; text-align: center; font-size: 12px; color: var(--muted); }
.si .wave-l .on { color: var(--accent); font-weight: 700; }
/* pagina Oggi: onda con un punto per paese, matrice paesi x asset, scala del Risk On/Off */
.si .wave.many { height: 220px; margin: 0 8px; }
.si .wave.many b { width: 14px; height: 14px; margin: -7px 0 0 -7px; box-shadow: 0 0 0 3px var(--surface); }
.si .wave .wl { position: absolute; transform: translate(-50%, -190%); font-size: 12px; font-weight: 700; white-space: nowrap;
  background: var(--raised); padding: 1px 7px; border-radius: 999px; }
.si .wave .wl.dn { transform: translate(-50%, 90%); }
.si .wave-a { gap: 16px; text-align: left; font-size: 13px; }
.si .wave-a div { display: flex; flex-direction: column; gap: 4px; }
.si .wave-a b { font-size: 15px; }
.si .mxg { display: grid; grid-template-columns: minmax(84px, 1fr) minmax(130px, 1.2fr) repeat(4, minmax(96px, 1fr)); gap: 6px 8px;
  align-items: center; font-size: 14px; min-width: 620px; }
.si .mx { height: 38px; border-radius: 10px; display: flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; background: var(--raised); }
.si .mx.opp { gap: 8px; font-size: 15px; }
.si .mx.opp .dot { width: 8px; height: 8px; }
.si .rscale { position: relative; padding-top: 6px; }
.si .rscale b { position: absolute; top: 0; width: 4px; height: 22px; margin-left: -2px; border-radius: 2px; background: var(--fg); box-shadow: 0 0 0 3px var(--surface); }
.si .rbands { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 3px; font-size: 11px; line-height: 14px; color: var(--muted); }
.si .rbands .on { color: var(--fg); font-weight: 700; }

/* barre */
.si .track { height: 8px; border-radius: 4px; background: var(--raised); overflow: hidden; }
.si .track i { display: block; height: 100%; border-radius: 4px; }
.si .prow { display: grid; grid-template-columns: 112px minmax(0, 1fr) 44px; gap: 12px; align-items: center; font-size: 14px; min-height: 30px; }
.si .r { text-align: right; }

/* asse: indicatore di posizione rispetto alle soglie */
.si .gauge { position: relative; height: 34px; margin-top: 4px; }
.si .gauge .bar { position: absolute; top: 12px; left: 0; right: 0; height: 10px; border-radius: 5px;
  background: linear-gradient(90deg, color-mix(in srgb, var(--lo) 55%, transparent) 0 30%, var(--raised) 30% 70%, color-mix(in srgb, var(--hi) 55%, transparent) 70%); }
.si .gauge b { position: absolute; top: 4px; width: 4px; height: 26px; border-radius: 2px; background: var(--fg); transform: translateX(-2px); box-shadow: 0 0 0 3px var(--surface); }
.si .gauge-l { display: flex; justify-content: space-between; font-size: 12px; color: var(--muted); }
.si .big { font-family: 'DM Mono', monospace; font-size: 30px; line-height: 34px; font-weight: 500; letter-spacing: -0.02em; }

/* card della Panoramica: frase semplice, gruppi di regime, righe con barra */
.si .say { font-size: 15px; line-height: 22px; }
.si .grp { display: flex; flex-direction: column; gap: 6px; padding: 10px 0; border-bottom: 1px solid var(--line); }
.si .grp:last-child { border-bottom: 0; }
.si .grp .top { display: flex; align-items: baseline; gap: 8px; font-size: 14px; }
.si .grp .top small { flex: 1; min-width: 0; font-size: 12px; color: var(--muted); }
.si .grp .muted { font-size: 13px; }
.si .chips { display: flex; flex-wrap: wrap; gap: 5px; }
.si .brow { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 10px; align-items: baseline; font-size: 14px; padding: 5px 0; }
.si .brow small { grid-column: 1 / -1; font-size: 12px; color: var(--muted); margin-top: -4px; }
.si .brow .track, .si .brow .seg { grid-column: 1 / -1; }
.si .seg { display: flex; gap: 3px; }
.si .seg i { flex: 1; height: 10px; border-radius: 3px; }
.si .total { display: flex; align-items: baseline; gap: 10px; padding-top: 12px; border-top: 1px solid var(--line); }

/* elenco righe (stile lista raggruppata) */
.si .list { display: flex; flex-direction: column; }
.si .list .row { display: flex; align-items: center; gap: 12px; padding: 11px 0; border-bottom: 1px solid var(--line); font-size: 14px; }
.si .list .row:last-child { border-bottom: 0; }
.si .list .row .grow { flex: 1 1 auto; min-width: 0; }

/* quadrante */
.si .quad { position: relative; aspect-ratio: 1.25; border-radius: 14px; overflow: hidden; border: 1px solid var(--line); }
.si .quad .q { position: absolute; width: 50%; height: 50%; }
.si .quad .ql { position: absolute; font-size: 12px; font-weight: 600; color: var(--muted); }
.si .quad .ax-v { position: absolute; left: 50%; top: 0; bottom: 0; width: 1px; background: var(--line); }
.si .quad .ax-h { position: absolute; top: 50%; left: 0; right: 0; height: 1px; background: var(--line); }
.si .quad .pt { position: absolute; width: 14px; height: 14px; margin: -7px 0 0 -7px; border-radius: 50%; border: 2px solid var(--surface); box-shadow: 0 1px 4px rgba(0,0,0,.25); }
.si .quad .pl { position: absolute; transform: translateY(-50%); font-size: 12px; font-weight: 700; color: var(--fg); white-space: nowrap; }

/* ciambella del portafoglio */
.si .donut { position: relative; width: 220px; aspect-ratio: 1; margin: 4px auto; border-radius: 50%; }
.si .donut .c { position: absolute; inset: 0; z-index: 2; pointer-events: none; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.si .donut .c b { font: 500 36px 'DM Mono', monospace; }
.si .donut .s { position: absolute; inset: 0; border-radius: 50%; transition: transform .15s; }
.si .donut .s:hover { transform: scale(1.03); }
.si .donut .hole { position: absolute; inset: 28px; border-radius: 50%; background: var(--surface); z-index: 1; }
.si .donut .c.tip { display: none; padding: 0 44px; text-align: center; line-height: 1.25; }
.si .donut:has(.s:hover) .c.def { display: none; }
.si .donut:has(.s0:hover) .c.t0 { display: flex; }
.si .donut:has(.s1:hover) .c.t1 { display: flex; }
.si .donut:has(.s2:hover) .c.t2 { display: flex; }
.si .donut:has(.s3:hover) .c.t3 { display: flex; }
.si .donut:has(.s4:hover) .c.t4 { display: flex; }
.si .donut:has(.s5:hover) .c.t5 { display: flex; }
.si .donut:has(.s6:hover) .c.t6 { display: flex; }
.si .donut:has(.s7:hover) .c.t7 { display: flex; }
.si .donut:has(.s8:hover) .c.t8 { display: flex; }
.si .donut:has(.s9:hover) .c.t9 { display: flex; }
.si .donut:has(.s10:hover) .c.t10 { display: flex; }
.si .donut:has(.s11:hover) .c.t11 { display: flex; }
.si .wrow { display: grid; grid-template-columns: 10px minmax(0, 1.4fr) minmax(40px, 1fr) 44px 36px; align-items: center; gap: 12px; min-height: 34px; font-size: 14px; }
.si .sw { width: 10px; height: 10px; border-radius: 3px; }

/* calendario, eventi, COT */
.si .ev-next { display: flex; align-items: center; gap: 14px; padding: 12px; border-radius: 14px; background: color-mix(in srgb, var(--accent) 12%, transparent); }
.si .ev-next .d { width: 58px; height: 58px; border-radius: 14px; background: var(--accent); color: var(--on-accent); display: flex; flex-direction: column; align-items: center; justify-content: center; font: 500 24px/1 'DM Mono', monospace; flex: none; }
.si .ev-next .d small { font: 600 11px 'Plus Jakarta Sans', sans-serif; margin-top: 2px; }
.si .cal h4 { margin: 18px 0 2px; padding: 0; font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--muted); }
.si .cal h4:first-child { margin-top: 0; }
.si .cal h4 b { color: var(--accent); margin-left: 8px; }
.si .cal .row { display: grid; grid-template-columns: 46px 46px 10px minmax(0, 1fr) auto; }
.si .cal .row.holiday { opacity: .55; }
.si .cal .v { font: 400 13px 'DM Mono', monospace; color: var(--muted); text-align: right; }
.si .cal .v b { color: var(--fg); font-weight: 500; }
.si .div { position: relative; height: 10px; border-radius: 5px; background: var(--raised); }
.si .div::before { content: ""; position: absolute; left: 50%; top: -3px; width: 1px; height: 16px; background: var(--muted); }
.si .div i { position: absolute; top: 0; height: 10px; background: var(--muted); }
.si .cot { display: grid; grid-template-columns: minmax(84px, 1fr) minmax(60px, 2fr) 56px 44px; gap: 12px; align-items: center; font-size: 14px; }
.si .arow { display: grid; grid-template-columns: 22px minmax(0, 1.8fr) minmax(70px, 1fr) 62px 62px 52px 32px; gap: 12px; align-items: center; min-height: 44px; font-size: 14px; border-bottom: 1px solid var(--line); }
.si .arow:last-child { border-bottom: 0; }

/* tabelle numeriche */
.si .tbl { overflow-x: auto; }
.si table.mtx { width: 100%; border-collapse: collapse; font-size: 13px; }
.si .mtx th { font-size: 11px; font-weight: 600; color: var(--muted); text-align: right; padding: 6px 8px; white-space: nowrap; }
.si .mtx td { padding: 7px 8px; text-align: right; border-top: 1px solid var(--line); font-family: 'DM Mono', monospace; white-space: nowrap; }
.si .mtx td:first-child { text-align: left; font-family: inherit; }
.si .mtx td.n { color: var(--muted); }
/* equivalenti UCITS (cards.ucits_html): testo a sinistra che va a capo, solo l'ISIN in colonna fissa */
.si .mtx.ucits th, .si .mtx.ucits td { text-align: left; font-family: inherit; white-space: normal; vertical-align: top; }
.si .mtx.ucits td.isin { font-family: 'DM Mono', monospace; white-space: nowrap; }
.si .arow.th { min-height: 28px; font-size: 12px; color: var(--muted); }

@media (prefers-reduced-motion: no-preference) {
  .si .card { animation: si-in .35s ease-out both; }
}
@keyframes si-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@media (max-width: 640px) {
  .si .card { padding: 18px; }
  .si .wrow { grid-template-columns: 10px minmax(0, 1fr) 44px 36px; }
  .si .wrow .track { display: none; }
  .si .cot { grid-template-columns: minmax(70px, 1fr) minmax(60px, 2fr) 56px; }
  .si .cot .lbl { display: none; }
  .si .prow { grid-template-columns: 96px minmax(0, 1fr) 40px; }
  .si .arow { grid-template-columns: 22px minmax(0, 1fr) 52px 32px; }
  .si .arow .opt { display: none; }
  .si .wave-a { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: 14px; }
  .si .wave .wl { font-size: 11px; padding: 1px 5px; }
  .si .mxg { grid-template-columns: minmax(64px, 1fr) repeat(4, minmax(0, 1fr)); min-width: 0; gap: 5px; font-size: 13px; }
  .si .mxg .ph { display: none; }
  .si .mxg > b { color: var(--c); }
  .si .mxg .eyebrow { font-size: 9px; letter-spacing: .02em; }
  .si .mx { height: auto; min-height: 34px; padding: 4px 2px; font-size: 11px; line-height: 1.2; text-align: center; }
  .si .mx.opp { gap: 4px; font-size: 12px; }
}
